p12_case('real_search_threshold_exact_dedupe_and_no_private_dimensions',function()use($persist,$metrics,$term,$db,$daily,$events,$run,$today,$getTotal,$beforeSearch,$beforeZero){$requests=[];$observers=[];for($i=0;$i<4;$i++){$observers[$i]=hash('sha256',$run.':observer:'.$i);$requests[$i]=bin2hex(random_bytes(16));p12_assert($persist->invoke($metrics,['locale'=>'en_US','zero'=>$i<2,'term'=>$term,'request'=>$requests[$i]],$observers[$i]),'Four distinct observers');}p12_assert((int)$db->value("SELECT COUNT(*) FROM $daily WHERE dimension_type='search_term' AND dimension_key=%s",[$term])===0,'Belowfive term plaintext absent');p12_assert((int)$db->value("SELECT COUNT(*) FROM $events WHERE dimension_key=%s",[$term])===0,'Raw term never in event dimensions');$data=['locale'=>'en_US','zero'=>false,'term'=>$term,'request'=>$requests[0]];p12_assert(!$persist->invoke($metrics,$data,$observers[0]),'Same proof replay deduped');$data['request']=bin2hex(random_bytes(16));p12_assert($persist->invoke($metrics,$data,$observers[0]),'New search same observer sitecount');p12_assert((int)$db->value("SELECT COUNT(*) FROM $daily WHERE dimension_type='search_term' AND dimension_key=%s",[$term])===0,'Same observer cannot inflate threshold');$data['request']=bin2hex(random_bytes(16));p12_assert($persist->invoke($metrics,$data,hash('sha256',$run.':observer:5')),'Fifth unique observer');$rows=$db->rows("SELECT metric_name,metric_count FROM $daily WHERE dimension_type='search_term' AND dimension_key=%s AND stat_day=%s",[SearchPrivacy::dimension($term),$today]);$counts=array_column($rows,'metric_count','metric_name');p12_assert((int)$counts['search_term']===5&&(int)$counts['no_result_term']===2,'Threshold publishes exact five/two aggregate');p12_assert($getTotal('search')===$beforeSearch+6&&$getTotal('search_no_result')===$beforeZero+2,'Six valid searches two noresult');$rows=$db->rows("SELECT dimension_type,dimension_key,dedupe_key FROM $events WHERE policy_version=%s AND event_day=%s",[SearchMetrics::POLICY,$today]);foreach($rows as$r){p12_assert(preg_match('/^[a-f0-9]{64}$/D',$r['dedupe_key'])===1,'Opaque dedupe only');p12_assert($r['dimension_key']==='all'||preg_match('/^[a-f0-9]{64}$/D',$r['dimension_key'])===1,'No IP/account/term in event dimensions');}});
